pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: newOwner and caller
    function testFuzz_property(address newOwner, address caller) public {
        // avoid the zero address for clarity (still broad domain)
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(0));

        // ensure caller has ETH to be able to be a msg.sender in vm.prank
        vm.deal(caller, 1 ether);

        // initial owner is deployer (this test contract), so we must perform the setOwner call from the owner
        // c was deployed in setUp by this contract, so this contract is owner. We'll have this contract call setOwner
        // but we fuzz the target newOwner and also check behavior when the call is proxied by a different caller.

        // First: as the real owner (this contract), set owner to 'caller' so that 'caller' becomes owner in reference
        bool ok;
        try c.setOwner(caller) {
            ok = true;
        } catch {
            ok = false;
        }
        // ensure this initial step succeeded; if it reverts, further scenario not admissible
        vm.assume(ok);

        // Now perform the interesting call: the current owner is 'caller'. The fuzzed actor 'caller' will invoke setOwner(newOwner).
        vm.prank(caller);
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // General property: after an authorized setOwner(newOwner) call, c.owner() equals the provided newOwner.
        // This holds for the reference contract for all inputs; the mutant that assigns owner = msg.sender breaks it
        // whenever newOwner != caller. We express the property via the public getter.
        assertTrue(c.owner() == newOwner);
    }
}

