contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: forwarder deployer (an address) and the desired newOwner
    // We fuzz two addresses: caller (who will be msg.sender to the forwarder) and newOwner (the value to set)
    function testFuzz_property(address caller, address newOwner) public {
        // Keep addresses in the normal EOA range (not zero) but otherwise wide
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));

        // Deploy a forwarder that will call c.setOwner(newOwner) — this makes msg.sender == address(forwarder)
        // but tx.origin == caller when the caller triggers the forwarder. The reference checks msg.sender,
        // so it will allow the forwarder (if forwarder is current owner). To create a meaningful scenario,
        // we will have the original owner (deployer of c) set the owner to the forwarder first, then
        // have the fuzzed caller invoke the forwarder to set owner to newOwner. Under the correct contract,
        // owner becomes newOwner (since msg.sender is forwarder). Under the mutant (which checks tx.origin),
        // tx.origin==caller, so unless caller==forwarder, the mutant may revert or not allow the change.

        // Deploy forwarder
        Forwarder f = new Forwarder(c);

        // current owner is address(this) because setUp created c with msg.sender == address(this)
        // Transfer ownership to the forwarder by calling setOwner from the current owner (this)
        bool ok;
        try c.setOwner(address(f)) { ok = true; } catch { ok = false; }
        // The reference must allow this (we are msg.sender == owner), so require that to hold for admissible inputs
        assertTrue(ok);
        // Now have the fuzzed caller invoke the forwarder to set owner to newOwner.
        // The action will be: caller (tx.origin and msg.sender for EOA) calls Forwarder.callSetOwner(newOwner),
        // which calls c.setOwner(newOwner) so in that inner call: msg.sender == address(forwarder), tx.origin == caller.

        vm.prank(caller);
        try f.forwardSetOwner(newOwner) { ok = true; } catch { ok = false; }

        // The universal property we assert: after the forwarded call, the correct contract's owner equals newOwner.
        // This must hold for ALL admissible inputs (any caller, any newOwner) because the reference checks msg.sender
        // and the immediate caller of c.setOwner is the forwarder, so the reference will accept and set owner.
        assertTrue(c.owner() == newOwner);
    }
}

// Minimal forwarder that calls c.setOwner
contract Forwarder {
    C immutable target;
    constructor(C _target) { target = _target; }
    function forwardSetOwner(address _owner) external {
        // forward the call to target
        target.setOwner(_owner);
    }
}

