import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantOwner attacker;

    function setUp() public {
        c = new C();
        // deploy reentrant attacker; it will become owner by being the deployer of this test contract? No—make attacker the owner by transferring ownership via c.setOwner
        attacker = new ReentrantOwner(address(c));
        // make attacker the owner: current owner is this test contract (deployer of C in setUp), so call setOwner to attacker
        // msg.sender must be owner; setUp runs as this contract, which is deployer of C, so valid
        c.setOwner(address(attacker));
        // verify attacker is now owner
        assertEq(c.owner(), address(attacker));
    }

    // fuzz parameter is the newOwner address to set; keep domain wide
    function testFuzz_property(address newOwner) public {
        // wide admissible domain: allow any address (including zero)
        // Let attacker (which is the current owner) call setOwner and re-enter during the call
        // The attacker will attempt to re-enter and perform an observation/interaction that can distinguish an insertion of owner = address(0) before assignment

        // tell attacker which target to set
        attacker.setTarget(newOwner);

        // invoke attacker to call c.setOwner(newOwner) as itself
        attacker.callSetOwner();

        // After the successful call, the general rule: c.owner() == newOwner
        // This is the single assertion: reference C satisfies for all inputs; mutant (which wrote owner = address(0) before setting) can be observed/broken by a reentrant owner.
        assertTrue(c.owner() == newOwner);
