// Minimal reentrant owner: it is the owner of C and when calling setOwner it re-enters C in its fallback to observe/modify state.
contract ReentrantOwner {
    address public target;
    C public c;

    constructor(address _c) {
        c = C(_c);
    }

    function setTarget(address _t) external {
        target = _t;
    }

    // entry point: call setOwner as this contract (the owner)
    function callSetOwner() external {
        // call C.setOwner from this contract
        c.setOwner(target);
    }

    // fallback invoked if C were to send Ether or call into this contract; also acts as reentrancy during any external calls
    fallback() external payable {
        // perform a read of c.owner() during the external call
        // For the mutant which sets owner = address(0) before assigning, an external observation during the call could see address(0)
        // Do a no-op read to simulate observation; also attempt a harmless reentrant call that does not change final owner but exercises ordering
        address current = c.owner();
        // attempt a benign call that will succeed; use a view via staticcall to avoid state change
        (bool ok, ) = address(c).staticcall(abi.encodeWithSignature("owner()"));
        // silence unused vars
        if (!ok) { revert(); }
    }
}

