        // Attacker will call setOwner and will NOT re-enter here; owner must be msg.sender
        // We need to call setOwner as the current owner. c was deployed in setUp() with owner = address(this)
        // So current owner is this test contract. We'll have the test contract call setOwner.

        // Call setOwner from this contract (which is c.owner()) to set the owner to the fuzzed newOwner
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: whenever the call succeeds, c.owner() equals the provided newOwner.
        // This must hold for the reference contract for ALL inputs; the mutant that assigns owner = address(0)
        // before assigning _owner can be distinguished by the fuzzer for some input (e.g., if intermediate
        // state matters or ordering changes observable behavior). We assert the single property below.
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If the call reverted, then the property about "successful call" does not apply; assert true tautology
            // but per rules we must have exactly one assertTrue reading c. To satisfy that, when call reverted,
            // we assert that owner was unchanged (owner == address(this)) — this still reads c and is true for reference.
            assertTrue(c.owner() == address(this));
        }
    }
}

