pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameters:
    // - address ownerProxy: an address we will deploy a tiny forwarding contract at (fuzzer supplies the initial address as a seed)
    // - address newOwner: the new owner value passed into setOwner
    // We need at least one fuzz param per rules; using both to let fuzzer explore scenarios.
    function testFuzz_property(address ownerProxy, address newOwner) public {
        // Make sure ownerProxy is not the zero address to keep it admissible
        vm.assume(ownerProxy != address(0));

        // The deployed C's constructor sets owner = msg.sender (this test contract).
        // We want to observe behavior when the legitimate owner (this test contract) calls setOwner
        // BUT routed THROUGH an intermediate contract (a forwarder) so that msg.sender != tx.origin.
        // Deploy a minimal forwarder whose execute() calls c.setOwner(...)
        Forwarder f = new Forwarder(c);

        // Ensure the forwarder's address is not zero (it won't be), and use it as the proxy
        // Call setOwner via the forwarder: the forwarder will call c.setOwner(newOwner) with msg.sender == forwarder
        // From the reference contract this should succeed because c.owner == address(this) (the test contract)
        // Wait: c.owner was set to msg.sender in constructor, which was this test contract; but we need the forwarder to act
        // on behalf of the owner. So first, have the owner (this test contract) set the owner of c to the forwarder's address.
        // We perform a direct call as the current owner (this contract) to set owner = address(f).
        bool ok;
        try c.setOwner(address(f)) {
            ok = true;
        } catch {
            ok = false;
        }
        // This must succeed on the reference implementation for all inputs: the current owner (this test contract)
        // calling setOwner directly (msg.sender == owner) must be allowed.
        assertTrue(ok);

        // Now, route a call through the forwarder: the forwarder will call c.setOwner(newOwner).
        // On the reference contract, onlyOwner checks msg.sender == owner. At this point owner == address(f), and msg.sender == address(f)
        // for the forwarded call, so it should succeed.
        bool ok2;
        try f.callSetOwner(newOwner) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // The universal property we assert: after the above steps, the forwarded call (forwarder -> c.setOwner)
        // succeeds when the forwarder is the current owner. The mutant which also requires msg.sender == tx.origin
        // will reject this forwarded call (because msg.sender == forwarder but tx.origin == this test contract),
        // causing ok2 to be false for some inputs; hence the assertion distinguishes reference vs mutant.
        assertTrue(ok2);
    }
}

// Minimal forwarder that calls c.setOwner on behalf of its caller
contract Forwarder {
    C immutable target;
    constructor(C _target) {
        target = _target;
    }
    function callSetOwner(address _owner) external {
        // simply forward the call to target.setOwner
        target.setOwner(_owner);
    }
}
